<?php require_once __DIR__.'/includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){validarCsrf();$acao=$_POST['acao'];if($acao==='excluir'){$id=(int)$_POST['id'];$pdo->prepare("UPDATE artigos SET ativo=false,atualizado_em=CURRENT_TIMESTAMP WHERE id=?")->execute([$id]);registrarAuditoria($pdo,usuarioAtual()['id'],'EXCLUIR','artigos',$id,'Desativação');}else{$id=(int)($_POST['id']??0);$cat=(int)$_POST['categoria_id'];$titulo=trim($_POST['titulo']);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT',$titulo)));$desc=trim($_POST['descricao']);$conteudo=trim($_POST['conteudo']);$preco=(float)str_replace(',','.',$_POST['preco_base']??0);$imagem=null;if(!empty($_FILES['imagem']['tmp_name'])&&is_uploaded_file($_FILES['imagem']['tmp_name'])){$info=@getimagesize($_FILES['imagem']['tmp_name']);if($info&&in_array($info['mime'],['image/jpeg','image/png'],true)){$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0755,true);$file=$slug.'_'.time().'.jpg';$src=$info['mime']==='image/jpeg'?imagecreatefromjpeg($_FILES['imagem']['tmp_name']):imagecreatefrompng($_FILES['imagem']['tmp_name']);$w=imagesx($src);$h=imagesy($src);$nw=min(1200,$w);$nh=(int)($h*$nw/$w);$out=imagecreatetruecolor($nw,$nh);imagecopyresampled($out,$src,0,0,0,0,$nw,$nh,$w,$h);imagejpeg($out,$dir.'/'.$file,85);imagedestroy($src);imagedestroy($out);$imagem='../uploads/'.$file;}}if($id){$q=$pdo->prepare("UPDATE artigos SET categoria_id=?,titulo=?,slug=?,descricao=?,conteudo=?,preco_base=?,imagem=COALESCE(?,imagem),atualizado_em=CURRENT_TIMESTAMP WHERE id=?");$q->execute([$cat,$titulo,$slug,$desc,$conteudo,$preco,$imagem,$id]);}else{$q=$pdo->prepare("INSERT INTO artigos(categoria_id,titulo,slug,descricao,conteudo,preco_base,imagem) VALUES(?,?,?,?,?,?,?) RETURNING id");$q->execute([$cat,$titulo,$slug,$desc,$conteudo,$preco,$imagem]);$id=$q->fetchColumn();}registrarAuditoria($pdo,usuarioAtual()['id'],$id?'ALTERAR':'INCLUIR','artigos',$id,'CRUD de serviço');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM artigos WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$cats=$pdo->query("SELECT * FROM categorias WHERE ativo=true ORDER BY nome")->fetchAll();$rows=$pdo->query("SELECT a.*,c.nome categoria FROM artigos a JOIN categorias c ON c.id=a.categoria_id ORDER BY a.id DESC")->fetchAll(); ?>
<section><h1>Serviços (Artigos)</h1><div class="form-card"><form method="post" enctype="multipart/form-data" data-validar><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Categoria</label><select name="categoria_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['categoria_id']??'')==$c['id']?'selected':''?>><?=e($c['nome'])?></option><?php endforeach;?></select><label>Título</label><input name="titulo" value="<?=e($edit['titulo']??'')?>" required><label>Descrição</label><textarea name="descricao" required><?=e($edit['descricao']??'')?></textarea><label>Conteúdo/detalhes</label><textarea name="conteudo" required><?=e($edit['conteudo']??'')?></textarea><label>Valor base</label><input type="number" step="0.01" name="preco_base" value="<?=e($edit['preco_base']??0)?>"><label>Imagem (upload + redimensionamento)</label><input type="file" name="imagem" accept="image/jpeg,image/png"><button>Salvar</button></form></div>
<div class="table-wrap"><table><tr><th>Título</th><th>Categoria</th><th>Valor</th><th>Ações</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['titulo'])?></td><td><?=e($r['categoria'])?></td><td><?=valorBR($r['preco_base'])?></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=$r['id']?>">Editar</a><form method="post" data-confirmar="Desativar este serviço?"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Desativar</button></form></div></td></tr><?php endforeach;?></table></div></section>
<?php require_once __DIR__.'/includes/footer.php'; ?>
